{
  "findings": [
    {
      "check_id": "CKV_AZURE_102",
      "title": "Azure SQL Database does not have Threat Detection enabled",
      "resource": "azurerm_mssql_database.trading_database",
      "severity": "HIGH",
      "explanation": "The azurerm_mssql_database resource does not have threat detection enabled, which can lead to undetected potential security threats."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_database\" \"trading_database\" {\n  name           = \"trading-database\"\n  server_id      = azurerm_mssql_server.trading_sql_server.id\n  collation      = \"SQL_Latin1_General_CP1_CI_AS\"\n  license_type   = \"LicenseIncluded\"\n  max_size_gb    = 100\n  sku_name       = \"S2\"\n  zone_redundant = false\n  threat_detection_policy {\n    state = \"Enabled\"\n  }\n}",
  "fix_summary": "Added threat detection policy to the azurerm_mssql_database resource to enable threat detection."
}
